#ifndef SOURCE_GROUP_SETTINGS_SCIP_H
#define SOURCE_GROUP_SETTINGS_SCIP_H

#include "SourceGroupSettingsCustomCommand.h"

// A source group indexed by a SCIP indexer built on the language's compiler
// (rust-analyzer for Rust, scip-dotnet on Roslyn for C#) and converted into
// the database by scip2sourcetrail (src/scip2sourcetrail).
//
// The first source path is the project: the directory of Cargo.toml for
// Rust, or the directory (or file) of the .sln/.csproj for C#. The SCIP index
// is cached next to the project file and regenerated by scip2sourcetrail
// when the sources change, so batches of files reuse one indexer run.
class SourceGroupSettingsScip : public SourceGroupSettingsCustomCommand
{
public:
	SourceGroupSettingsScip(
		SourceGroupType type, const std::string& id, const ProjectSettings* projectSettings);

	std::shared_ptr<SourceGroupSettings> createCopy() const override;

	void loadSettings(const ConfigManager* config) override;

	// Rebuilds the command from the current source paths. Called when the
	// group is created for indexing, after the paths are final.
	void updateCommand();

	// "rust" or "csharp": the --generate value of scip2sourcetrail.
	std::string getIndexerId() const;

	// Where the SCIP index of this group is cached.
	FilePath getScipFilePath() const;

	// scip2sourcetrail as deployed (<app>/data/scip), from
	// SOURCETRAIL_SCIP2SOURCETRAIL, or a cargo build in the source tree.
	static FilePath findConverterFilePath();

private:
	void applyDefaults();
};

#endif	  // SOURCE_GROUP_SETTINGS_SCIP_H
